SELECT FROM roles WHERE status = COALESCE(#{status}, status)
AND name LIKE CONCAT('%', #{name}, '%')
ORDER BY sort_order ASC, id ASC LIMIT #{offset}, #{pageSize}

SELECT FROM permissions WHERE status = COALESCE(#{status}, status)
AND name LIKE CONCAT('%', #{name}, '%')
AND resource = #{resource}
ORDER BY sort_order ASC, id ASC LIMIT #{offset}, #{pageSize}

SELECT FROM departments WHERE status = COALESCE(#{status}, status)
AND name LIKE CONCAT('%', #{name}, '%')
ORDER BY sort_order ASC, id ASC LIMIT #{offset}, #{pageSize}
